CREATE TABLE IF NOT EXISTS customer_appointment_slots(id UUID PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('OUTREACH','HOSPITAL')),company_id TEXT NOT NULL DEFAULT '',location TEXT NOT NULL,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL,capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 500),cutoff_minutes INTEGER NOT NULL DEFAULT 60 CHECK(cutoff_minutes BETWEEN 0 AND 10080),status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(ends_at>starts_at),CHECK((type='HOSPITAL' AND company_id='') OR(type='OUTREACH' AND company_id<>'')),UNIQUE(type,company_id,location,starts_at));CREATE TABLE IF NOT EXISTS customer_appointments(id UUID PRIMARY KEY,slot_id UUID NOT NULL REFERENCES customer_appointment_slots(id),record_key TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES checkup_projects(id),status TEXT NOT NULL DEFAULT 'BOOKED' CHECK(status IN ('BOOKED','ARRIVED','COMPLETE','NO_SHOW','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());CREATE UNIQUE INDEX IF NOT EXISTS customer_appointments_active_idx ON customer_appointments(record_key,project_id) WHERE status<>'CANCELLED';CREATE INDEX IF NOT EXISTS customer_appointments_slot_idx ON customer_appointments(slot_id,status);